# Ch6 مرکب (E-10) - part B: phrases inside sentences, murakkab-e-masadir
T, E, C, M, S = "مرکبِ توصیفی", "مرکبِ اضافی", "مرکبِ عطفی", "مرکبِ تام", "مرکبِ مصادر"
def sent(lvl, s, ans, why, extra=M):
    ops = [x for x in (T, E, C, extra) if x != ans][:3]
    if len(ops) < 3: ops = [x for x in (T, E, C, M, S) if x != ans][:3]
    return (lvl, s + "<br>خط کشیدہ ترکیب کس قسم کا مرکب ہے؟", ans, *ops, why)

